using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Returns information about a message. Returns a 404 error if the message doesn't exist
    /// </summary>
    public Task<TdLib.TdApi.Objects.Message> GetMessageAsync(long chatId = default, long messageId = default)
    {

           using var activity =  StartCallActivity("GetMessageAsync", typeof(GetMessage).FullName ?? "GetMessageAsync");

           try
           {
             return client.GetMessageAsync(chatId, messageId);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
